//! Runtime contract between the backend and the generic frontend.
//!
//! [`ComponentData`] is what a component receives when it asks for its data.
//! The other types are the envelopes of the HTTP API. TypeScript bindings of
//! everything here are generated by `cargo xtask gen-types`.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::id::{ComponentId, DatasetId, StateKey};
use crate::spec::{ChartMark, DashboardSpec};

/// The application state: one JSON value per state entry.
///
/// A column selection holds a column name or `null`; a filter input holds a
/// [`Filter`](crate::Filter) or `null`.
pub type StateMap = BTreeMap<StateKey, Value>;

/// Everything the frontend needs to render a dashboard on start-up.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct AppInfo {
    /// Version of the Eario framework serving the dashboard.
    pub eario_version: String,
    /// The dashboard to render.
    pub spec: DashboardSpec,
    /// Current application state.
    pub state: StateMap,
    /// Number of state changes since start-up.
    pub revision: u64,
    /// Stored user preferences.
    pub preferences: Preferences,
}

/// Result of a change: the new state and the components it made stale.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct StateUpdate {
    /// Number of state changes since start-up, after this one.
    pub revision: u64,
    /// The complete application state after the change.
    pub state: StateMap,
    /// Components whose data must be fetched again.
    pub invalidated: Vec<ComponentId>,
}

/// User preferences, stored on the local machine between runs.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct Preferences {
    /// Preferred colour theme.
    #[serde(default)]
    pub theme: Theme,
}

/// Colour theme of the user interface.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "snake_case")]
pub enum Theme {
    /// Follow the operating system preference.
    #[default]
    System,
    /// Light theme.
    Light,
    /// Dark theme.
    Dark,
}

/// Error body returned by the HTTP API.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct ApiError {
    /// Stable, machine-readable error code.
    pub code: String,
    /// Message that can be shown to the user.
    pub message: String,
}

/// The data of one component, as returned by the backend.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ComponentData {
    /// The component has nothing to show yet, for the given reason.
    Empty {
        /// Why there is nothing to show, in words meant for the user.
        reason: String,
    },
    /// Data of a text component: none.
    Text,
    /// Data of a file import or dataset information component.
    Dataset {
        /// Metadata of the loaded dataset.
        info: DatasetInfo,
    },
    /// Data of a column selection: the columns on offer.
    ColumnSelect {
        /// Names of the columns the user can choose from.
        options: Vec<String>,
    },
    /// Data of a filter input: the columns that can be filtered.
    FilterInput {
        /// Columns of the dataset.
        columns: Vec<ColumnInfo>,
    },
    /// Data of a table: one page of rows.
    DataTable {
        /// The requested page.
        table: TablePage,
    },
    /// Data of a chart.
    Chart {
        /// Points to draw.
        chart: ChartData,
    },
    /// Data of a statistics component.
    Statistics {
        /// One row of statistics per numeric column.
        stats: StatsTable,
    },
}

/// Metadata of a loaded dataset.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct DatasetInfo {
    /// Slot the dataset is loaded into.
    pub id: DatasetId,
    /// Name of the source, usually the imported file name.
    pub source_name: String,
    /// Name of the source format, for example `csv` or `xlsx`.
    pub format: String,
    /// Size of the source, in bytes.
    pub source_bytes: u64,
    /// Number of rows.
    pub rows: u32,
    /// Columns, in order.
    pub columns: Vec<ColumnInfo>,
    /// Worksheets of the source; empty for formats without worksheets.
    pub sheets: Vec<String>,
    /// Worksheet currently loaded, for formats with worksheets.
    pub selected_sheet: Option<String>,
}

/// Metadata of one column.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct ColumnInfo {
    /// Column name.
    pub name: String,
    /// Broad category of the values.
    pub kind: ColumnKind,
    /// Name of the storage type, as reported by the data engine.
    pub dtype: String,
    /// Number of missing values.
    pub null_count: u32,
}

/// Broad category of the values of a column.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "snake_case")]
pub enum ColumnKind {
    /// Integers or floating-point numbers.
    Numeric,
    /// Text.
    Text,
    /// Booleans.
    Boolean,
    /// Anything else.
    Other,
}

/// One page of the rows of a view.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct TablePage {
    /// Column names, in order.
    pub columns: Vec<String>,
    /// Rows of the page; each row has one JSON value per column.
    pub rows: Vec<Vec<Value>>,
    /// Position of the first row of the page within the view.
    pub offset: u32,
    /// Number of rows in the view, after filtering.
    pub total_rows: u32,
    /// Number of rows in the dataset, before filtering.
    pub unfiltered_rows: u32,
}

/// Points of a chart, already reduced to what the frontend should draw.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct ChartData {
    /// How points are drawn.
    pub mark: ChartMark,
    /// Name of the horizontal-axis column.
    pub x_label: String,
    /// Name of the vertical-axis column.
    pub y_label: String,
    /// Points, as `[x, y]` pairs, in row order.
    pub points: Vec<[f64; 2]>,
    /// Number of drawable points in the view before downsampling.
    pub total_points: u32,
    /// Number of rows left out because a coordinate was missing or not finite.
    pub skipped_rows: u32,
}

/// Descriptive statistics of the numeric columns of a view.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct StatsTable {
    /// Number of rows in the view.
    pub rows: u32,
    /// One entry per numeric column.
    pub columns: Vec<ColumnStats>,
}

/// Descriptive statistics of one numeric column.
///
/// A statistic is `None` when it is undefined, for example the mean of a
/// column holding only missing values.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS), ts(export))]
pub struct ColumnStats {
    /// Column name.
    pub column: String,
    /// Number of values that are not missing.
    pub count: u32,
    /// Number of missing values.
    pub null_count: u32,
    /// Arithmetic mean.
    pub mean: Option<f64>,
    /// Sample standard deviation (denominator `count - 1`).
    pub std: Option<f64>,
    /// Smallest value.
    pub min: Option<f64>,
    /// Median.
    pub median: Option<f64>,
    /// Largest value.
    pub max: Option<f64>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn component_data_variants_are_tagged() -> Result<(), serde_json::Error> {
        let empty = ComponentData::Empty { reason: "No dataset loaded.".to_owned() };
        assert_eq!(
            serde_json::to_value(&empty)?,
            serde_json::json!({ "type": "empty", "reason": "No dataset loaded." })
        );
        assert_eq!(
            serde_json::to_value(ComponentData::Text)?,
            serde_json::json!({ "type": "text" })
        );
        Ok(())
    }

    #[test]
    fn preferences_default_to_system_theme_when_field_is_missing() -> Result<(), serde_json::Error>
    {
        let preferences: Preferences = serde_json::from_str("{}")?;
        assert_eq!(preferences.theme, Theme::System);
        Ok(())
    }
}
